function chars(s, k) {
  const c = {};
  let l = 0, best = 0, mx = 0;
  for (let r = 0; r < s.length; r++) {
    c[s[r]] = (c[s[r]] || 0) + 1;
    mx = Math.max(mx, c[s[r]]);
    if (r - l + 1 - mx > k) c[s[l++]]--;
    best = Math.max(best, r - l + 1);
  }
  return best;
}
