function subarraySum(nums, k) {
  const c = new Map([[0, 1]]);
  let sum = 0, count = 0;
  for (const n of nums) {
    sum += n;
    count += c.get(sum - k) || 0;
    c.set(sum, (c.get(sum) || 0) + 1);
  }
  return count;
}
