```js
function permute(nums) {
  const res = [];
  const bt = (path, rem) => {
    if (!rem.length) return res.push([...path]);
    for (let i = 0; i < rem.length; i++) {
      path.push(rem[i]);
      bt(path, [...rem.slice(0, i), ...rem.slice(i + 1)]);
      path.pop();
    }
  };
  bt([], nums);
  return res;
}
```

