```js
function daily(T) {
  const res = new Array(T.length).fill(0), st = [];
  for (let i = 0; i < T.length; i++) {
    while (st.length && T[st[st.length - 1]] < T[i]) {
      const j = st.pop();
      res[j] = i - j;
    }
    st.push(i);
  }
  return res;
}
```

Boyer-Moore voting.
```js
function dominator(A) {
  let cand = -1, count = 0, idx = -1;
  for (let i = 0; i < A.length; i++) {
    if (count === 0) { cand = A[i]; count = 1; idx = i; }
    else count += A[i] === cand ? 1 : -1;
  }
  const total = A.filter(x => x === cand).length;
  return total > A.length / 2 ? idx : -1;
}
```

