function numIslands(g) {
  const R = g.length, C = g[0].length;
  let n = 0;
  const dfs = (r, c) => {
    if (r < 0 || c < 0 || r >= R || c >= C || g[r][c] !== '1') return;
    g[r][c] = '0';
    dfs(r+1,c); dfs(r-1,c); dfs(r,c+1); dfs(r,c-1);
  };
  for (let r = 0; r < R; r++)
    for (let c = 0; c < C; c++)
      if (g[r][c] === '1') { dfs(r, c); n++; }
  return n;
}
```

