function climb(n) {
  let a = 1, b = 1;
  for (let i = 2; i <= n; i++) [a, b] = [b, a + b];
  return b;
}
```

```js
function rob(nums) {
  let prev2 = 0, prev1 = 0;
  for (const n of nums) [prev2, prev1] = [prev1, Math.max(prev1, prev2 + n)];
  return prev1;
}
```

Bucket sort by count — O(n).
```js
function topK(nums, k) {
  const c = new Map();
  for (const n of nums) c.set(n, (c.get(n) || 0) + 1);
  const buckets = Array.from({ length: nums.length + 1 }, () => []);
  for (const [n, f] of c) buckets[f].push(n);
  const res = [];
  for (let i = buckets.length - 1; res.length < k; i--) res.push(...buckets[i]);
  return res.slice(0, k);
}
```

